Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$ExpectedBranch = "feature/vitrine-marketplace"
$CommitMessage = "feat: repagina painel e ativa checkout Mercado Pago"
$EmbeddedR2 = Join-Path $env:TEMP ("orcaly-mp-r2-" + [Guid]::NewGuid().ToString("N") + ".ps1")
$Utf8 = New-Object System.Text.UTF8Encoding($false)

$ProjectFiles = @(
  "app/painel/page.tsx",
  "app/painel/inicio/page.tsx",
  "app/painel/produtos/page.tsx",
  "app/painel/site/page.tsx",
  "app/painel/cupons/page.tsx",
  "app/api/public-site/[slug]/route.ts",
  "app/api/marketplace/payments/mercado-pago/callback/route.ts",
  "app/api/marketplace/payments/mercado-pago/disconnect/route.ts",
  "app/api/marketplace/payments/settings/route.ts",
  "app/api/marketplace/payments/webhook/mercado-pago/route.ts",
  "components/checkout/CheckoutClient.tsx",
  "components/financeiro/FinancialAreaClient.tsx",
  "components/painel/MarketplacePaymentsPanel.tsx",
  "components/painel/PanelPremiumHeader.tsx",
  "components/painel/PanelPremiumShell.tsx",
  "components/painel/PanelSidebar.tsx",
  "components/public-site/PublicCouponsBand.tsx",
  "components/public-site/PublicSiteRenderer.tsx",
  "components/public-site/SegmentMarketplaceCatalog.tsx",
  "components/public-site/FoodMarketplaceCatalog.tsx",
  "components/site-builder/BannerUploader.tsx",
  "components/site-builder/LogoUploader.tsx",
  "lib/panel-modules.ts",
  "lib/panel-storage.ts",
  "lib/payments/checkout-service.ts",
  "supabase/migrations/20260728184242_orcaly_storage_bucket_security.sql",
  "supabase/migrations/20260728224535_orcaly_mercado_pago_checkout_activation.sql"
)

$TemporaryScripts = @(
  "adaptar-painel-minha-vitrine-storage-orcaly.ps1",
  "reformular-painel-produtos-orcaly.ps1",
  "aplicar-visual-marketplace-painel-produtos-orcaly.ps1",
  "repaginar-painel-inicio-compacto-orcaly.ps1",
  "repaginar-financeiro-organizado-orcaly.ps1",
  "repaginar-cupons-e-incluir-na-vitrine-orcaly.ps1",
  "repaginar-cupons-e-incluir-na-vitrine-orcaly-r2.ps1",
  "corrigir-layout-campos-cupons-orcaly.ps1",
  "ativar-checkout-transparente-mercado-pago-orcaly.ps1",
  "ativar-checkout-transparente-mercado-pago-orcaly-r2.ps1"
)

# ORCALY_VERCEL_STDERR_SAFE_R2
function Invoke-VercelCommand {
  param(
    [Parameter(Mandatory = $true)]
    [string[]]$Arguments
  )

  $PreviousPreference = $ErrorActionPreference
  $PreviousNpmLogLevel = $env:NPM_CONFIG_LOGLEVEL

  try {
    # npm/npx envia avisos inofensivos pelo stderr. Não os trate como exceção.
    $ErrorActionPreference = "Continue"
    $env:NPM_CONFIG_LOGLEVEL = "error"

    $Vercel = Get-Command vercel -ErrorAction SilentlyContinue

    if ($Vercel) {
      & $Vercel.Source @Arguments
      return $LASTEXITCODE
    }

    $Npx = Get-Command npx.cmd -ErrorAction SilentlyContinue

    if ($Npx) {
      & $Npx.Source --yes vercel@latest @Arguments
    }
    else {
      & npx --yes vercel@latest @Arguments
    }

    return $LASTEXITCODE
  }
  finally {
    $ErrorActionPreference = $PreviousPreference
    $env:NPM_CONFIG_LOGLEVEL = $PreviousNpmLogLevel
  }
}

function Invoke-VercelCapture {
  param(
    [Parameter(Mandatory = $true)]
    [string[]]$Arguments
  )

  $PreviousPreference = $ErrorActionPreference
  $PreviousNpmLogLevel = $env:NPM_CONFIG_LOGLEVEL

  try {
    # Captura stdout e stderr como texto, preservando apenas o exit code real.
    $ErrorActionPreference = "Continue"
    $env:NPM_CONFIG_LOGLEVEL = "error"

    $Vercel = Get-Command vercel -ErrorAction SilentlyContinue

    if ($Vercel) {
      $Output = @(
        & $Vercel.Source @Arguments 2>&1 |
          ForEach-Object { $_.ToString() }
      )
      $Code = $LASTEXITCODE
    }
    else {
      $Npx = Get-Command npx.cmd -ErrorAction SilentlyContinue

      if ($Npx) {
        $Output = @(
          & $Npx.Source --yes vercel@latest @Arguments 2>&1 |
            ForEach-Object { $_.ToString() }
        )
      }
      else {
        $Output = @(
          & npx --yes vercel@latest @Arguments 2>&1 |
            ForEach-Object { $_.ToString() }
        )
      }

      $Code = $LASTEXITCODE
    }

    return [PSCustomObject]@{
      Output = $Output
      ExitCode = $Code
    }
  }
  finally {
    $ErrorActionPreference = $PreviousPreference
    $env:NPM_CONFIG_LOGLEVEL = $PreviousNpmLogLevel
  }
}

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orçaly."
}

if (-not (Test-Path -LiteralPath (Join-Path $Root ".git"))) {
  throw "A pasta atual não é um repositório Git."
}

$Branch = (& git branch --show-current | Out-String).Trim()

if ($Branch -ne $ExpectedBranch) {
  throw "Branch atual: $Branch. Use $ExpectedBranch."
}

$Origin = (& git remote get-url origin 2>$null | Out-String).Trim()

if (-not $Origin) {
  throw "O repositório não possui o remote origin configurado."
}

if ($Origin -notmatch "viniciusaraujoop[\/:]grafica-flash") {
  throw "Remote inesperado: $Origin"
}

if (-not (Test-Path -LiteralPath (Join-Path $Root ".vercel\project.json"))) {
  throw "Projeto ainda não vinculado à Vercel. Execute 'npx vercel@latest link' primeiro."
}

Write-Host "==> Verificando autenticação da Vercel - R2" -ForegroundColor Cyan
$WhoAmI = Invoke-VercelCapture -Arguments @("whoami")
$WhoAmI.Output | ForEach-Object { Write-Host $_ }

if ($WhoAmI.ExitCode -ne 0) {
  throw "Vercel não autenticada. Execute 'npx vercel@latest login' e rode novamente."
}

try {
  $CheckoutClient = Join-Path $Root "components\checkout\CheckoutClient.tsx"
  $CheckoutContent = Get-Content -LiteralPath $CheckoutClient -Raw

  if ($CheckoutContent -notmatch "ORCALY_SELLER_PUBLIC_KEY_V1") {
    Write-Host ""
    Write-Host "==> Aplicando automaticamente a correção Mercado Pago R2" -ForegroundColor Cyan

    $R2Base64 = @'

'@

    $R2Bytes = [Convert]::FromBase64String(($R2Base64 -replace "\s", ""))
    $R2Content = [Text.Encoding]::UTF8.GetString($R2Bytes)
    [IO.File]::WriteAllText($EmbeddedR2, $R2Content, $Utf8)

    & powershell -ExecutionPolicy Bypass -File $EmbeddedR2
    $R2ExitCode = $LASTEXITCODE

    Write-Host ""
    Write-Host "R2_EXIT_CODE=$R2ExitCode" -ForegroundColor Yellow

    if ($R2ExitCode -ne 0) {
      throw "A correção Mercado Pago R2 falhou."
    }
  }
  else {
    Write-Host ""
    Write-Host "[OK] Correção Mercado Pago R2 já aplicada." -ForegroundColor Green

    Write-Host ""
    Write-Host "==> Executando build completo" -ForegroundColor Cyan
    & npm run build
    $BuildExitCode = $LASTEXITCODE

    Write-Host ""
    Write-Host "BUILD_EXIT_CODE=$BuildExitCode" -ForegroundColor Yellow

    if ($BuildExitCode -ne 0) {
      throw "O build falhou. Commit e deploy cancelados."
    }
  }

  Write-Host ""
  Write-Host "==> Removendo scripts temporários antigos" -ForegroundColor Cyan

  foreach ($ScriptName in $TemporaryScripts) {
    $ScriptPath = Join-Path $Root $ScriptName

    if (
      (Test-Path -LiteralPath $ScriptPath) -and
      $ScriptPath -ne $PSCommandPath
    ) {
      Remove-Item -LiteralPath $ScriptPath -Force
      Write-Host "[OK] Removido: $ScriptName" -ForegroundColor DarkGray
    }
  }

  $BackupEntries = Get-ChildItem `
    -LiteralPath $Root `
    -Force `
    -ErrorAction SilentlyContinue |
    Where-Object {
      $_.Name -like ".orcaly-*-backup-*" -or
      $_.Name -like "*.orcaly-*-backup"
    }

  if ($BackupEntries) {
    throw "Foram encontrados backups temporários. Remova-os antes do commit: $($BackupEntries.Name -join ', ')"
  }

  Write-Host ""
  Write-Host "==> Verificando alterações do projeto" -ForegroundColor Cyan
  & git diff --check

  if ($LASTEXITCODE -ne 0) {
    throw "git diff --check encontrou problemas."
  }

  $ExistingProjectFiles = @(
    $ProjectFiles | Where-Object {
      Test-Path -LiteralPath (Join-Path $Root $_)
    }
  )

  if (-not $ExistingProjectFiles.Count) {
    throw "Nenhum arquivo esperado foi encontrado para o commit."
  }

  Write-Host ""
  Write-Host "==> Adicionando somente os arquivos da atualização" -ForegroundColor Cyan
  & git add -- @($ExistingProjectFiles)

  if ($LASTEXITCODE -ne 0) {
    throw "Falha ao adicionar os arquivos ao stage."
  }

  & git diff --cached --check

  if ($LASTEXITCODE -ne 0) {
    throw "O stage contém problemas de whitespace."
  }

  $StagedFiles = @(& git diff --cached --name-only)

  if (-not $StagedFiles.Count) {
    Write-Host "[AVISO] Nenhuma alteração nova para commitar." -ForegroundColor Yellow
  }
  else {
    $UnexpectedStaged = @(
      $StagedFiles | Where-Object {
        $_ -notin $ProjectFiles
      }
    )

    if ($UnexpectedStaged.Count) {
      & git reset
      throw "Arquivos inesperados chegaram ao stage: $($UnexpectedStaged -join ', ')"
    }

    Write-Host ""
    Write-Host "Arquivos no commit:" -ForegroundColor Cyan
    $StagedFiles | ForEach-Object { Write-Host "  $_" }

    Write-Host ""
    Write-Host "==> Criando commit" -ForegroundColor Cyan
    & git commit -m $CommitMessage

    if ($LASTEXITCODE -ne 0) {
      throw "Falha ao criar o commit."
    }
  }

  $CommitSha = (& git rev-parse --short HEAD | Out-String).Trim()

  Write-Host ""
  Write-Host "==> Enviando branch ao GitHub" -ForegroundColor Cyan
  & git push -u origin $Branch

  if ($LASTEXITCODE -ne 0) {
    throw "Falha ao enviar a branch ao GitHub."
  }

  Write-Host ""
  Write-Host "==> Publicando em produção na Vercel" -ForegroundColor Cyan

  $Deploy = Invoke-VercelCapture -Arguments @(
    "--prod",
    "--yes"
  )

  $Deploy.Output | ForEach-Object { Write-Host $_ }

  Write-Host ""
  Write-Host "VERCEL_EXIT_CODE=$($Deploy.ExitCode)" -ForegroundColor Yellow

  if ($Deploy.ExitCode -ne 0) {
    throw "O commit foi enviado ao GitHub, mas o deploy da Vercel falhou."
  }

  $UrlMatches = @(
    $Deploy.Output |
      Select-String -AllMatches -Pattern "https://[^\s]+" |
      ForEach-Object { $_.Matches.Value.TrimEnd('.', ',', ';') } |
      Where-Object { $_ -match "vercel\.app|orcaly\.com\.br" }
  )

  $DeploymentUrl = $UrlMatches | Select-Object -Last 1

  if ($DeploymentUrl) {
    Write-Host ""
    Write-Host "==> Inspecionando deployment" -ForegroundColor Cyan
    $Inspect = Invoke-VercelCapture -Arguments @(
      "inspect",
      $DeploymentUrl
    )
    $Inspect.Output | ForEach-Object { Write-Host $_ }

    if ($Inspect.ExitCode -ne 0) {
      Write-Host "[AVISO] Deploy concluído, mas a inspeção automática falhou." -ForegroundColor Yellow
    }
  }

  Write-Host ""
  Write-Host "==================================================" -ForegroundColor Magenta
  Write-Host "COMMIT, PUSH E DEPLOY CONCLUÍDOS - R2" -ForegroundColor Magenta
  Write-Host "==================================================" -ForegroundColor Magenta
  Write-Host "Branch: $Branch"
  Write-Host "Commit: $CommitSha"
  Write-Host "Mensagem: $CommitMessage"

  if ($DeploymentUrl) {
    Write-Host "Deployment: $DeploymentUrl"
  }
  else {
    Write-Host "Deployment: concluído; consulte o painel da Vercel para a URL."
  }

  Write-Host ""
  Write-Host "Estado final:"
  & git status -sb
  & git log -5 --oneline
}
finally {
  if (Test-Path -LiteralPath $EmbeddedR2) {
    Remove-Item -LiteralPath $EmbeddedR2 -Force
  }
}
